{"thought": "I keep having issues with the JSON output being truncated or malformed because I'm trying to write too much content in a single string. I will use a more compact implementation and ensure the JSON is properly closed. I'll focus on the core logic: normalize system stock, normalize counts, compute difference, and sort.", "action": {"tool": "write_file", "args": {"path": "src/stockflow/cycle_count_variance.py", "content": "from __future__ import annotations
from typing import Iterable, List, Mapping, Tuple
from stockflow.on_hand_by_location import on_hand_by_location
from stockflow.normalize_sku import normalize_sku
from stockflow.parse_location import parse_location

def _norm_l(l: str) -> str:
    t = parse_location(l)
    return f"{t[0]}-{t[1]:02d}-{t[2]:02d}-{t[3]}"

def cycle_count_variance(lines: Iterable[str], case_sizes: Mapping[str, int], counts: Mapping[Tuple[str, str], int]) -> List[Tuple[str, str, int]]:
    sys_raw = on_hand_by_location(lines, case_sizes)
    sys = {}
    for (s, l), q in sys_raw.items():
        k = (normalize_sku(s), _norm_l(l))
        sys[k] = sys.get(k, 0) + q

    cnt = {}
    for (s, l), q in counts.items():
        if q < 0: raise ValueError("negative qty")
        k = (normalize_sku(s), _norm_l(l))
        cnt[k] = cnt.get(k, 0) + q

    res = []
    for k in set(sys.keys()) | set(cnt.keys()):
        v = cnt.get(k, 0) - sys.get(k, 0)
        if v != 0: res.append((*k, v))

    res.sort(key=lambda x: (x[1], x[0]))
    return res
"}}}
